import{_ as t,o as r,c as s,a3 as i}from"./chunks/framework.DhF4LrUq.js";const o="/shipperdog/snapshot/screenshots/console-devices.png",v=JSON.parse('{"title":"Manage the device fleet","description":"Manage the device fleet - register tester devices by hand, correct metadata, park devices, and export the provisioning CSV.","frontmatter":{"description":"Manage the device fleet - register tester devices by hand, correct metadata, park devices, and export the provisioning CSV."},"headers":[],"relativePath":"how-to/console/devices.md","filePath":"how-to/console/devices.md"}'),a={name:"how-to/console/devices.md"};function n(d,e,c,l,h,p){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="manage-the-device-fleet" tabindex="-1">Manage the device fleet <a class="header-anchor" href="#manage-the-device-fleet" aria-label="Permalink to &quot;Manage the device fleet&quot;">​</a></h1><p>Each tenant keeps a registry of its testers&#39; devices — the iOS UDIDs your App Store build must be provisioned for, the Android devices your support team correlates reports against. The registry lives one tenant deep: Tenants — <strong>Devices</strong>.</p><p><img src="'+o+'" alt="The tenant device registry"></p><p>Why registration is manual — and why devices are never deleted — is covered in <a href="/shipperdog/snapshot/concepts/security-model">the security model</a>.</p><h2 id="register-a-device" tabindex="-1">Register a device <a class="header-anchor" href="#register-a-device" aria-label="Permalink to &quot;Register a device&quot;">​</a></h2><ol><li><p>Open <strong>Tenants</strong>, click <strong>Devices</strong> on the tenant&#39;s row.</p></li><li><p>Click <strong>Register device</strong> and fill the form:</p><ul><li><strong>Owner (linked tester)</strong> — the tester this device belongs to (picked from the tenant&#39;s testers).</li><li><strong>Platform</strong> — iOS or Android.</li><li><strong>Identifier (UDID / serial)</strong> — the device&#39;s unique identifier, unique within the tenant. A UDID cannot be captured from a web page, so the tester reads it off their device (Settings — General — About on iOS; the vendor&#39;s instructions on Android) and hands it to you.</li><li><strong>Model</strong> and <strong>OS version</strong> — optional descriptive fields.</li></ul></li><li><p>Click <strong>Register</strong>.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">Keep the OS version honest</p><p>The registry&#39;s descriptive fields feed the feedback context testers&#39; reports carry — a corrected OS version today is a better-diagnosed bug report tomorrow.</p></div><h2 id="work-the-registry" tabindex="-1">Work the registry <a class="header-anchor" href="#work-the-registry" aria-label="Permalink to &quot;Work the registry&quot;">​</a></h2><ul><li><strong>Platform</strong> and <strong>Status</strong> filters narrow the grid; <strong>Load more</strong> pages.</li><li><strong>Edit</strong> corrects the model and OS version — the descriptive facts may change as devices update; the identifier never does.</li><li><strong>Deactivate</strong> parks a device reversibly: a deactivated tester&#39;s records stay (the support history posture), and <strong>Reactivate</strong> brings the device back. Devices are never deleted.</li></ul><h2 id="export-the-provisioning-list" tabindex="-1">Export the provisioning list <a class="header-anchor" href="#export-the-provisioning-list" aria-label="Permalink to &quot;Export the provisioning list&quot;">​</a></h2><p><strong>Export CSV</strong> produces the store-side provisioning list — one row per device with its identifier, platform, model, OS, and owner email. Upload it to the Apple developer portal (or your MDM) when the beta profile&#39;s device list needs a refresh.</p><h2 id="devices-and-feedback" tabindex="-1">Devices and feedback <a class="header-anchor" href="#devices-and-feedback" aria-label="Permalink to &quot;Devices and feedback&quot;">​</a></h2><p>When a report arrives from a registered device, the release dashboard&#39;s feedback row shows the device context automatically — model, OS — because the registry linked it. Registration is what turns &quot;crashes on some iPhone&quot; into &quot;crashes on iPhone 13, iOS 17.4&quot;. See <a href="/shipperdog/snapshot/how-to/console/feedback-triage">triage feedback</a>.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/tenants">manage tenants</a> · <a href="/shipperdog/snapshot/how-to/console/feedback-triage">triage feedback</a> · <a href="/shipperdog/snapshot/roles/tenant-admin">tenant-admin quickstart</a></p>',14)])])}const f=t(a,[["render",n]]);export{v as __pageData,f as default};
